struct IoState{unsigned calls,opens,closes,failAt,throwAt,cancelAt;HANDLE cancel;IoState():calls(0),opens(0),closes(0),failAt(0),throwAt(0),cancelAt(0),cancel(NULL){}bool Step(){++calls;if(calls==cancelAt)SetEvent(cancel);if(calls==throwAt)throw 1;return calls!=failAt;}};
