// WorldPixels::Triangle. This checks source height after actual file readback.
static double Height(const FixedTerrain::Samples&s,double x,double z){double sx=(x+147456)/18,sz=(z+147456)/18;unsigned ix=unsigned(floor(sx)),iz=unsigned(floor(sz));double u=sx-ix,v=sz-iz;unsigned vx[3]={ix,ix+1,ix},vz[3]={iz,iz,iz+1};if(u+v>1){vx[0]=ix+1;vz[0]=iz+1;}double p[3][3];for(unsigned i=0;i<3;++i){p[i][0]=-147456+double(vx[i])*18;p[i][2]=-147456+double(vz[i])*18;unsigned short raw=s.data[size_t(vz[i]-s.minZ)*s.stride+vx[i]-s.minX];p[i][1]=float(raw*(9800.f/65535.f));}double ax=p[1][0]-p[0][0],ay=p[1][1]-p[0][1],az=p[1][2]-p[0][2],bx=p[2][0]-p[0][0],by=p[2][1]-p[0][1],bz=p[2][2]-p[0][2];double nx=ay*bz-az*by,ny=az*bx-ax*bz,nz=ax*by-ay*bx;return p[0][1]-(nx*(x-p[0][0])+nz*(z-p[0][2]))/ny;}
